export type RIconName = keyof typeof DEFS;

/**
 * The glyphs are drawn smaller in their 20 grid (about 15 of 20) than
 * lucide's in its 24 (about 20 of 24), so they are drawn 1.15x inside the
 * same box: the box, and the layout round it, stay as they were (Figmama
 * 11-18). The lines stay 1px (non-scaling).
 */
const GLYPH_SCALE = 1.15;
const VIEW = 20 / GLYPH_SCALE;
const VIEW_BOX = `${(20 - VIEW) / 2} ${(20 - VIEW) / 2} ${VIEW} ${VIEW}`;

const paint = (v?: "c" | "k") => (v === "c" ? "currentColor" : v === "k" ? "var(--layer-canvas)" : "none");

export function RIcon({ name, filled = false, ...props }: { name: RIconName; filled?: boolean } & SVGProps<SVGSVGElement>) {
  const def: Def = DEFS[name];
  const parts = filled && def.f ? def.f : def.o;
  return (
    <svg viewBox={VIEW_BOX} width="20" height="20" overflow="visible" fill="none" strokeLinecap="butt" strokeLinejoin="miter" aria-hidden="true" data-ricon={name} {...props}>
      {parts.map((p, i) => (
        <path key={i} d={p.d} stroke={paint(p.s)} fill={paint(p.f)} fillRule={p.e ? "evenodd" : undefined} style={p.s ? { strokeWidth: p.w ? `${p.w}px` : "var(--icon-stroke, 1px)" } : undefined} vectorEffect="non-scaling-stroke" />
      ))}
    </svg>
  );
}
